from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]/'assets/profile-borders-articulated'
DESCRIPTIONS={91:'별핵의 호흡과 결정 부유',92:'별 장식의 밝기·크기 변화',93:'불꽃의 뿌리 중심 흔들림',94:'기어 중심축 회전과 왕관 승강',95:'차원 결정의 벌어짐과 복귀',96:'가지 뿌리를 고정한 좌우 흔들림',97:'어깨·중간 관절과 겹친 깃털 묶음의 펼침·접힘',98:'용 머리의 작은 끄덕임과 구름 부유',99:'프리즘 결정의 펼침과 호흡',100:'천체 브래킷의 대칭 개폐'}
items=json.loads((ROOT/'manifest.json').read_text());cards=[]
for a in sorted(items,key=lambda a:(a['id']!=97,a['id'])):
 n=a['id'];files=[a['frame']]+[p['file'] for p in a['parts']]
 if n==97:files.append('097-upper-body.png')
 links=''.join(f'<a href="{p}" download><img src="{p}" loading="lazy" alt="독립 레이어 {i+1}"><span>레이어 {i+1}</span></a>' for i,p in enumerate(files))
 cards.append(f'<article><h2>{n} · {DESCRIPTIONS[n]}</h2><div class="poses"><figure><figcaption>기준 · 첫 업로드 844e7c2</figcaption><img src="../profile-borders/legendary/profile_{n:03}_legendary.png"></figure><figure><figcaption>닫힘 / 기본 자세</figcaption><img src="profile_{n:03}_closed.png"></figure><figure><figcaption>펼침 / 중간 자세</figcaption><img src="profile_{n:03}_open.png"></figure><figure><figcaption>실제 재생</figcaption><object type="image/svg+xml" data="profile_{n:03}_legendary.svg" aria-label="{n} 애니메이션"></object></figure></div><a href="profile_{n:03}_legendary.svg" download>재생용 SVG</a> · <a href="profile_{n:03}_closed.png" download>정지 PNG</a><details><summary>테두리와 완전한 독립 레이어 보기</summary><div class="layers">{links}</div></details></article>')
(ROOT/'index.html').write_text('''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>전설 관절·연결부 수정본</title><style>body{background:#e5eaf0;color:#20354b;font:15px system-ui;margin:24px}article{background:white;border-radius:12px;padding:20px;margin:24px 0}h2{font-size:18px}.poses{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}figure{margin:0}figcaption{font-size:12px;min-height:32px}figure img,object{width:100%;aspect-ratio:1;display:block;background:#dfe5ec;border-radius:8px}.layers{display:flex;flex-wrap:wrap;gap:12px}.layers a{width:120px}.layers img{width:120px;height:120px;object-fit:contain;background:#dfe5ec;display:block}summary{cursor:pointer;margin-top:16px}button{padding:10px 16px;border:1px solid #adbbc7;border-radius:8px;background:white;color:#20354b;margin-right:8px}a{color:#255775}.dark figure img,.dark object,.dark .layers img{background:#182436}@media(max-width:700px){.poses{grid-template-columns:repeat(2,minmax(0,1fr))}}</style><h1>전설 관절·연결부 수정본</h1><p>기준은 두 번째 수정 후 처음 업로드한 844e7c2입니다. 97번의 기준·닫힘·펼침·재생을 먼저 비교하고, 아래에서 나머지 전설을 확인할 수 있습니다.</p><p>테두리와 장식의 연결을 유지하면서 장식별 관절과 동작을 적용했습니다. 중앙 원은 지름 716px이며 완전 투명합니다.</p><button id="play">재생 / 일시정지</button><button id="fx">후광·명암 켜기 / 끄기</button><button id="bg">배경 밝기 변경</button>'''+''.join(cards)+'''<script>let paused=false,fx=true;document.querySelector('#play').onclick=()=>{paused=!paused;document.querySelectorAll('object').forEach(o=>o.contentDocument?.getAnimations().forEach(a=>paused?a.pause():a.play()))};document.querySelector('#fx').onclick=()=>{fx=!fx;document.querySelectorAll('object').forEach(o=>o.contentDocument?.querySelectorAll('.fx').forEach(e=>e.style.visibility=fx?'':'hidden'))};document.querySelector('#bg').onclick=()=>document.body.classList.toggle('dark');</script></html>''')
print('Preview:',len(items),'rigs, 097 first')
